using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Text;using System.Threading;using System.Runtime.InteropServices;
class ExportChecks{
delegate bool EnumProc(IntPtr w,IntPtr p);
[DllImport("user32.dll")]static extern bool EnumWindows(EnumProc f,IntPtr p);[DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr w,EnumProc f,IntPtr p);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr w,out uint p);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr w,StringBuilder b,int n);[DllImport("user32.dll")]static extern int GetDlgCtrlID(IntPtr w);[DllImport("user32.dll")]static extern IntPtr GetDlgItem(IntPtr w,int i);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr w,uint m,IntPtr a,IntPtr b);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr w);[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr w,uint m,IntPtr a,IntPtr b);[DllImport("user32.dll",CharSet=CharSet.Unicode,EntryPoint="SendMessageW")]static extern IntPtr SendText(IntPtr w,uint m,IntPtr a,string b);
static void Check(bool c,string n){if(!c)throw new Exception(n);Console.WriteLine("PASS: "+n);}static IntPtr Dialog(uint pid,IntPtr main){IntPtr found=IntPtr.Zero;EnumWindows((w,l)=>{uint id;GetWindowThreadProcessId(w,out id);var c=new StringBuilder(128);GetClassName(w,c,c.Capacity);if(id==pid&&w!=main&&IsWindowVisible(w)&&c.ToString()=="#32770"){found=w;return false;}return true;},IntPtr.Zero);return found;}
static IntPtr Filename(IntPtr dialog){IntPtr found=IntPtr.Zero;EnumChildWindows(dialog,(w,l)=>{var c=new StringBuilder(128);GetClassName(w,c,c.Capacity);if(GetDlgCtrlID(w)==1001&&c.ToString()=="Edit"){found=w;return false;}return true;},IntPtr.Zero);return found;}
static void Click(IntPtr parent,int id){SendMessage(GetDlgItem(parent,id),0xf5,IntPtr.Zero,IntPtr.Zero);Thread.Sleep(500);}static void Export(IntPtr w,Process p,string path){PostMessage(GetDlgItem(w,1049),0xf5,IntPtr.Zero,IntPtr.Zero);IntPtr dialog=IntPtr.Zero;for(int i=0;i<100;i++){dialog=Dialog((uint)p.Id,w);if(dialog!=IntPtr.Zero)break;Thread.Sleep(100);}Check(dialog!=IntPtr.Zero,"save dialog opens");IntPtr edit=Filename(dialog);Check(edit!=IntPtr.Zero,"filename field found");SendText(edit,0x0c,IntPtr.Zero,path);PostMessage(GetDlgItem(dialog,1),0xf5,IntPtr.Zero,IntPtr.Zero);for(int i=0;i<200&&!File.Exists(path);i++)Thread.Sleep(100);Check(File.Exists(path),"PNG saved to Chinese path");bool valid=false;for(int i=0;i<100;i++){try{using(var image=Image.FromFile(path)){valid=image.RawFormat.Guid==System.Drawing.Imaging.ImageFormat.Png.Guid&&image.Width>=500&&image.Height>300;}break;}catch(Exception){Thread.Sleep(100);}}Check(valid,"valid PNG has map and footer");}
static int Main(string[] a){Directory.CreateDirectory(a[1]);var s=new ProcessStartInfo(a[0]){WorkingDirectory=Path.GetDirectoryName(a[0]),UseShellExecute=false};s.EnvironmentVariables["LOCALAPPDATA"]=Path.Combine(a[1],"profile");var p=Process.Start(s);try{IntPtr w=IntPtr.Zero;for(int i=0;i<120;i++){p.Refresh();w=p.MainWindowHandle;if(w!=IntPtr.Zero&&IsWindowVisible(w)&&GetDlgItem(w,1065)!=IntPtr.Zero)break;Thread.Sleep(250);}Thread.Sleep(3000);Export(w,p,Path.Combine(a[1],"基础地图.png"));Click(w,1006);Click(w,1007);Export(w,p,Path.Combine(a[1],"人口NASA.png"));Click(w,1006);Click(w,1005);Click(w,1009);Click(w,1011);SendMessage(GetDlgItem(w,1046),0xf5,IntPtr.Zero,IntPtr.Zero);var combo=GetDlgItem(w,1041);SendMessage(combo,0x014e,(IntPtr)3,IntPtr.Zero);SendMessage(w,0x0111,(IntPtr)((1<<16)|1041),combo);Thread.Sleep(500);Export(w,p,Path.Combine(a[1],"图层路线地图.png"));Click(w,1024);Export(w,p,Path.Combine(a[1],"English-map.png"));PostMessage(GetDlgItem(w,1049),0xf5,IntPtr.Zero,IntPtr.Zero);IntPtr d=IntPtr.Zero;for(int i=0;i<100;i++){d=Dialog((uint)p.Id,w);if(d!=IntPtr.Zero)break;Thread.Sleep(100);}Check(d!=IntPtr.Zero,"save dialog reopens");PostMessage(GetDlgItem(d,2),0xf5,IntPtr.Zero,IntPtr.Zero);Thread.Sleep(500);Check(!p.HasExited,"cancel returns to application");return 0;}catch(Exception e){Console.WriteLine("FAIL: "+e.Message);return 1;}finally{if(!p.HasExited){var d=Dialog((uint)p.Id,p.MainWindowHandle);if(d!=IntPtr.Zero)PostMessage(d,0x10,IntPtr.Zero,IntPtr.Zero);PostMessage(p.MainWindowHandle,0x10,IntPtr.Zero,IntPtr.Zero);if(!p.WaitForExit(5000))p.Kill();}}}}




